def _try_ai_summarize(text: str, tool_name: str) -> str:
    """Try AI summarization for oversized tool results.

    Falls back to original text on any failure (no crash).
    """
    try:
        from nanobot.groupchat.history import history_settings as hs
        threshold = hs.summarize_threshold()
        if len(text) <= threshold:
            return text

        from nanobot.tools.summarizer import summarize_tool_output

        loop = asyncio.new_event_loop()
        try:
            asyncio.set_event_loop(loop)
            summarized = loop.run_until_complete(
                summarize_tool_output(tool_name, text)
            )
            if summarized and len(summarized) < len(text):
                logger.info(
                    "result_processor: AI summarized {} output: {}c → {}c (-{}%)",
                    tool_name, len(text), len(summarized),
                    round((1 - len(summarized) / len(text)) * 100),
                )
                return summarized
        finally:
            loop.close()
    except Exception as e:
        logger.debug("result_processor: AI summarize skipped for {}: {}", tool_name, e)
    return text


